/** Machine translated draft; religious and linguistic review pending. */
internal object DuaMaiDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_waking_up" to DuaText("जागैत समय", "समस्त प्रशंसा अल्लाह के लेल अछि, जे हमरा सभ केँ जीवन देलनि, जखन ओ हमरा सभ केँ मारि देलनि, आ हुनका लग फेरब अछि।", "नींदसँ उठबा पर अल्लाहकेँ धन्यवाद देब।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम जागैत काल ई पाठ कयलनि-दिनक शुरुआत आभार आ पराक स्मरणक सङ्ग कयल गेल।"),
        "dua_leaving_home" to DuaText("घरसँ बाहर निकलबऽ पर", "हम अल्लाह पर भरोसा करैत छी। अल्लाह के अतिरिक्त कोनो शक्ति आ शक्ति नहि अछि।", "घरसँ बाहर निकलबऽ पर, अल्लाह के सुरक्षा के लेल।", "स्वर्गदूत लोकनि कहैत छथि, \"अहाँ निर्देशित छी, अहाँक देखभाल कयल जाइत अछि आ अहाँ सुरक्षित छी\", आ शैतान चलि जाइत अछि।"),
        "dua_anxiety_distress" to DuaText("चिन्ता आ दुःखसँ राहत", "हे अल्लाह, हम अहाँ मे चिन्ता आ दुःख सँ, असहायता आ आलस्य सँ, दुर्दशा आ कायरता सँ, ऋणक बोझ सँ आ लोक सभक द्वारा हावी होयबाक सँ शरण चाहैत छी।", "दुख, चिन्ता, ऋण आ मानसिक क्लेशक समय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम बहुधा एहि दुआ केँ करैत छलाह-दुख, आलस्य आ ऋणक चिन्ता सँ शरण।"),
        "dua_sayyidul_istighfar" to DuaText("सैयद अल-इस्टिघफर (क्षमा के प्रमुख)", "ऐ अल्लाह, अहाँ हमर प्रभु छी, अहाँक अतिरिक्त ककरो पूजा करबाक अधिकार नहि अछि। अहाँ हमरा उत्पन्न कयलहुँ आ हम अहाँक दास छी, आ हम अहाँक वाचा आ प्रतिज्ञाक पालन करैत छी जे हम कऽ सकैत छी। हम अहाँ मे ओहि अधलाह काज सँ शरण चाहैत छी जे हम कयने छी। हम अहाँ पर अहाँक अनुग्रह स्वीकार करैत छी आ हम अपन पाप स्वीकार करैत छी, तेँ हमरा क्षमा कऽ दियौक, किएक तँ अहाँक अतिरिक्त कोनो पाप क्षमा नहि करैत अछि।", "भोर आ साँझ-पश्चातापक सबसँ नीक दुआ जे पैगम्बर सल्लल्लाहु अलैहि वसल्लम द्वारा सिखायल गेल अछि।", "जे केओ साँझ मे निश्चिततासँ ई कहैत अछि आ ओहि राति मरि जायत ओ स्वर्ग मे प्रवेश करत; जे भोर मे कहल जायत तँ ई लागू होयत।"),
        "dua_parents" to DuaText("माता-पिता के लेल प्रार्थना", "हे हमर प्रभु, अहाँ सभ हुनका सभ पर दया करू, जेना ओ सभ हमरा छोट होयबा पर उठौलनि।", "अपन माता-पिता लेल एकटा कुरानिक दुआ-बचपनमे हुनक देखभालक बदलामे।", "अल्लाह स्वयं हमरा सभकेँ आदेश देलनि जे हम सभ अपन माता-पिता लेल ई दुआ बनाउ।"),
        "dua_entering_mosque" to DuaText("मस्जिदमे प्रवेश", "ऐ अल्लाह, हमरा लेल अहाँक दयाक द्वार खोलू।", "जखन मस्जिदमे दाहिने पैरसँ प्रवेश करैत छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम मस्जिदमे प्रवेश करबाक लेल ई दुआ सिखौलनि।"),
        "dua_morning_asbahna" to DuaText("भोरक स्मरण", "भोर मे हम सभ प्रवेश कऽ लेलहुँ आ पूरा राज्य भोर मे अल्लाह के अछि। सब प्रशंसा अल्लाह के अछि। ककरो पूजा करबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदार के। शासन हुनकर अछि आ प्रशंसा हुनकर अछि, आ ओ सब चीज पर शक्ति अछि।", "भोरमे सुन्नत दुआ पठैत छल।", "एहि दिनक आरम्भ अल्लाहक संप्रभुता आ हुनकर एकताक पुष्टि सँ होइत अछि।"),
        "dua_evening_amsayna" to DuaText("साँझक स्मरण", "साँझ मे हम सभ प्रवेश कऽ लेलहुँ आ पूरा राज्य अल्लाह के साँझ मे प्रवेश कऽ गेल अछि। सब प्रशंसा अल्लाह के अछि। ककरो पूजा करबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदार के। शासन हुनकर अछि आ प्रशंसा हुनकर अछि, आ ओ सब चीज पर शक्ति अछि।", "साँझमे सुन्नत दुआ पठायल गेल।", "राति अल्लाहक संप्रभुता आ हुनकर एकताक पुष्टि सँ शुरू होइत अछि।"),
        "dua_bismillah_la_yadurru" to DuaText("सब नुकसानसँ सुरक्षा", "अल्लाह के नाम पर, जकर नाम सँ पृथ्वी पर या आकाश मे किछु हानि नहि कऽ सकैत अछि, आ ओ सब सुनने छथि, सब किछु जनैत छथि।", "तीन बेर प्रतिदिन भोर आ साँझ।", "जे केओ भोर-साँझ तीन बेर ई कहैत अछि, ओकरा कोनो हानि नहि होयत।"),
        "dua_raditu_billahi" to DuaText("प्रभुक रूपमे अल्लाहसँ संतुष्टि।", "हम अपन प्रभुक रूपमे अल्लाहसँ, अपन धर्मक रूपमे इस्लामसँ आ पैगम्बरक रूपमे मुहम्मद सल्लल्लाहु अलैहि वसल्लमसँ प्रसन्न छी।", "तीन बेर भोर आ साँझ।", "कयामतक दिन हुनका प्रसन्न करबाक अधिकार अल्लाह पर भऽ जाइत अछि।"),
        "dua_hasbiyallah" to DuaText("हसबियल्लाह (अल्लाह पर्याप्त अछि)", "हमरा लेल अल्लाह पर्याप्त छथि, हुनका छोड़ि कोनो देवता नहि छथि। हम हुनका पर भरोसा करैत छी आ ओ शक्तिशाली सिंहासनक प्रभु छथि।", "सात बेर भोर आ साँझ।", "कुरानक एकटा आयत-अल्लाह एहि संसार आ आखिरतक चिन्ता सभक विरुद्ध पर्याप्त छथि।"),
        "dua_subhanallah_wa_bihamdihi" to DuaText("सुभानअल्लाही वा बिहमदीही", "महिमावान छथि अल्लाह आ प्रशंसा सभ हुनकर अछि।", "एक सौ बेर एक दिन।", "जे केओ दिन मे सौ बेर ई कहैत अछि, ओकरा पाप माफ भऽ जायत, भले ओ समुद्रक झाग सन हो।"),
        "dua_tahleel_100" to DuaText("ला इलाहा इल्लल्लाहु वाहदहू", "ककरो पूज्य-पूज्य होयबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदारक। शासन हुनकर अछि, प्रशंसा सेहो हुनकर अछि, आ ओ सब चीज पर प्रभुत्व रखैत छथि।", "ई दिन मे सौ बेर कहने के बहुत बढ़िया गुण छैक।", "दस दासकेँ मुक्त करबाक, सौ नीक काज लिखबाक, सौ पाप मिटबाक आ साँझ धरि शैतानसँ सुरक्षा देबाक पुरस्कार।"),
        "dua_leaving_mosque" to DuaText("मस्जिद छोड़ते हुए", "ऐ अल्लाह, हम अहाँ सँ अहाँक अनुग्रह माँगैत छी।", "मस्जिदसँ बाहर निकलबाक समय बाएँ पैरसँ।", "मस्जिदसँ बाहर निकलबाक समय अल्लाहसँ अनुग्रह आ रोजी-रोटी माँगब।"),
        "dua_after_adhan" to DuaText("अधानक बाद", "ऐ अल्लाह, एहि पूर्ण आह्वान आ प्रार्थनाक स्वामी जे स्थापित होबय वाला अछि, मुहम्मद सल्लल्लाहु अलैहि वसिलाह आ सद्गुण प्रदान करू आ हुनका ओहि प्रशंसापूर्ण स्थान पर उठा लिअ जकर अहाँ हुनका वादा कयने छी।", "अधान पूरा भेलाक बाद।", "जे केओ ई कहैत अछि ओकरा न्यायक दिन पैगम्बर सल्लल्लाहु अलैहि वसल्लमक सिफ़ारिश देल जायत।"),
        "dua_after_salah_istighfar" to DuaText("फरद सलाहक बाद", "हम अल्लाहसँ क्षमा माँगैत छी (3 बेर)। हे अल्लाह, अहाँ सलम छी आ अहाँ सँ शान्ति अछि। धन्य छी अहाँ, हे महिमा आ सम्मानक स्वामी।", "सलमक तुरन्त बाद।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम प्रत्येक अनिवार्य नमाज़क बाद ई पाठ कयलनि।"),
        "dua_after_salah_help_dhikr" to DuaText("हमरा अहाँक स्मरण करबामे सहायता करू।", "हे अल्लाह, हमरा अहाँक स्मरण करबाक लेल, आभार व्यक्त करबाक लेल आ उत्तम तरीकासँ अहाँक पूजा करबाक लेल सहायता करू।", "प्रत्येक नमाज़क बाद पैगम्बर सल्लल्लाहु अलैहि वसल्लम मुआद (र) केँ ई कहबाक सलाह देलनि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम के एक विशेष सलाह-पूजा मे उत्कृष्टता आ स्थिरता।"),
        "dua_ayatul_kursi" to DuaText("सलाहक बाद आयत अल-कुर्सी", "अल्लाह-हुनका छोड़ि कोनो पूज्य-प्रभु नहि छथि, जे सर्वजीवी छथि, जे सभ केँ बचबैत छथि। हुनका लग न तन्द्रा आ न निद्रा अबैत अछि। आकाश-पृथ्वी मे जे किछु अछि, ओकरहि अछि। हुनकर अनुमति के बिना हुनकर संग सिफ़ारिश के कऽ सकैत अछि? ओ जनैत अछि जे हुनका सभक सामने आ ओकर पाछाँ की अछि, आ हुनकर ज्ञान मे से किछु नहि अछि सिवाय जे ओ चाहैत अछि। हुनकर कुर्सी आकाश-पृथ्वी पर पसरल अछि, आ हुनकर रखवाली कयनाइ हुनका थकय नहि दैत अछि। ओ सर्वोच्च, महान छथि।", "प्रत्येक अनिवार्य नमाज़क बाद आ सोबासँ पहिने।", "प्रत्येक अनिवार्य नमाज़क बाद एकर पाठ करयवला आ सोबासँ पहिने पठयवला स्वर्गक बीच मृत्युक अतिरिक्त किछु नहि रहैत अछि; ई भोर धरि सुरक्षा दैत अछि।"),
        "dua_before_sleep" to DuaText("सोबासँ पहिने", "ऐ अल्लाह, हम अहाँक नाम सँ मरैत छी (सोैत छी) आ जीवित रहैत छी (जागैत छी)।", "बिस्तर पर लेटला पर।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम सोबासँ पहिने ई पाठ कयलनि।"),
        "dua_sleep_tasbeeh" to DuaText("सोबासँ पहिने तसबीह-ए-फातिमा", "महिमावान अल्लाह (33), सब प्रशंसा अल्लाह (33) के लेल अछि, अल्लाह सबसँ महान (34) छथि।", "सोबासँ पहिने पैगम्बर सल्लल्लाहु अलैहि वसल्लम फातिमा आ अली (र) केँ ई सिखौलनि।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि जे ई अहाँक लेल सेवक सँ नीक अछि।"),
        "dua_sleep_qina_adhab" to DuaText("सजा सँ सुरक्षा", "ऐ अल्लाह, हमरा अपन सजा सँ बचाउ जाहि दिन अहाँ अपन दाससभ केँ जी उठाबऽ छी।", "तीन बेर, दाहिने हाथकेँ गालक नीचा रखै।", "नींदकेँ मृत्युक स्मरण आ पराक लेल तैयारीमे परिणत कऽ दैत अछि।"),
        "dua_bad_dream" to DuaText("एकटा खराब सपनाक बाद", "हम शापित शयतान सँ अल्लाह मे शरण चाहैत छी।", "एकटा खराब सपनाक बादः तीन बेर बाम दिस हल्का-हल्का थूकू, फेर दोसर दिस फेरू।", "खराब सपना अहाँकेँ कोनो हानि नहि पहुँचाएगा; एहि बारे मे ककरो नहि बताउ।"),
        "dua_yunus" to DuaText("पैगम्बर यूनुस (अ. स.) के दुआ", "अहाँक अतिरिक्त कोनो देवता नहि अछि; अहाँक महिमा होअय। हम तोँ सभ अधर्मी सभक बीच मे रहलहुँ।", "पैगम्बर यूनुस (ए. एस.) क दुआ व्हेलक पेटमे-हर कठिनाईक लेल।", "जे मुसलमान कोनो मामलामे ई दुआ करैत अछि, अल्लाह ओकरा जवाब दैत अछि।"),
        "dua_karb" to DuaText("दुखक समय दुआ (कार्ब)", "अल्लाह, जे शक्तिशाली, सहनशील छथि, हुनका छोड़ि ककरो पूजा करबाक अधिकार नहि अछि। अल्लाह, जे शक्तिशाली सिंहासनक स्वामी छथि, हुनका छोड़ि ककरो पूजा करबाक अधिकार नहि अछि। आकाशक प्रभु, पृथ्वीक प्रभु आ महान सिंहासनक स्वामी अल्लाहके छोड़ि ककरो पूजा करबाक अधिकार नहि अछि।", "गम्भीर कष्ट आ कष्टक समय।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम दुखक समय मे ई पाठ कयलनि।"),
        "dua_ya_hayyu_ya_qayyum" to DuaText("या हयू या कयूम", "ऐ सदा जीवित, ऐ सभ के पालनकर्ता! अहाँक दयासँ हम सहायता माँगैत छी।", "जखन कोनो मामला बहुत भारी भऽ जाइत अछि।", "जखन पैगम्बर सल्लल्लाहु अलैहि वसल्लम केँ कोनो बात परेशान करत तखन ओ ई कहैत छलाह।"),
        "dua_hasbunallah" to DuaText("हसबुनाल्लाहु वा निमाल वकील", "हमरा सभक लेल अल्लाह पर्याप्त छथि आ ओ सभ काजक सबसँ नीक निपटानकर्ता छथि।", "जखन कोनो दुश्मनसँ डरैत हो वा बड्ड खतराक सामना करैत हो।", "पैगम्बर इब्राहिम (अ. स.) एकरा आगिमे फेकल गेल पर कहलनि, आ पैगम्बर सल्लल्लाहु अलैहि वसल्लम एकरा खतराक समय कहलनि।"),
        "dua_entering_home" to DuaText("घर मे प्रवेश", "अल्लाह के नाम पर।", "घर मे प्रवेश करैत समय अल्लाह के नाम कहि कऽ सलाम के साथ नमस्कार करू।", "जखन अल्लाहकेँ भोजन आ प्रवेश पर स्मरण कयल जाइत अछि तखन शयतान कहैत छथिः एतऽ अहाँक लेल कोनो ठहरबाक स्थान नहि अछि आ रात्रिभोज सेहो नहि अछि।"),
        "dua_travel" to DuaText("दुआ यात्रा (सवारी)", "महिमावान छथि ओ जे अपना सभ केँ एहि बातक अधीन कयने छथि आ ई काज अपना सभ स्वयं नहि कऽ सकैत छलहुँ आ अपन प्रभुक ओहिठाम हम सभ अवश्य फिरब।", "गाड़ी पर बेसी तीन बेर अल्लाहू अकबर कहने के बाद।", "सुन्नत यात्रा दुआ-सुरक्षा आ आशीर्वादक लेल।"),
        "dua_entering_market" to DuaText("बाजार मे प्रवेश", "ककरो पूजा करबाक अधिकार नहि अछि सिवाय अल्लाह के, मात्र, बिना साझीदारक। शासन हुनकर अछि आ प्रशंसा हुनकर अछि। ओ जीवन दैत छथि आ मृत्यु दैत छथि, आ ओ जीवित छथि आ कहियो नहि मरि जाइत छथि। हुनकर हाथ मे सब किछु नीक अछि, आ ओ सब चीज पर शक्ति रखैत छथि।", "बजार मे प्रवेश करैत समय।", "हदीस मे एकर लेल एकटा पैघ पुरस्कार (दस लाख नीक काज) के उल्लेख छैक।"),
        "dua_adam_forgiveness" to DuaText("पैगम्बर आदम (अ. स.) के दुआ", "हे हमर प्रभु, अपना सभ अपन सभ पर अन्याय कयलहुँ आ जँ अहाँ सभ हमरा सभ पर क्षमा नहि करैत छी आ हमरा सभ पर दया नहि करैत छी तँ हम सभ अवश्य हानि पहुँचयवला सभक बीच मे रहब।", "आदम आ हवा (ए. एस.) क पश्चातापक दुआ।", "मानवताक पहिल पश्चाताप-अल्लाह एकरा स्वीकार कयलनि।"),
        "dua_abu_bakr" to DuaText("दुआ अबू बकर (र.) केँ पढ़बैत छल।", "ऐ अल्लाह, हम अपन ऊपर बहुत अन्याय कयलहुँ, आ अहाँक अतिरिक्त कोनो पाप क्षमा नहि करैत अछि, तेँ हमरा स्वयं क्षमा करू आ हमरा पर दया करू। निश्चय ही, अहाँ क्षमाशील, दयावान छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम अबू बकर अस-सिद्दीक (रा.) केँ प्रार्थना (ताशाहहुदक बाद) मे कहबाक शिक्षा देलनि।", "नमाज़क अन्त लेल सुन्नत दुआ।"),
        "dua_astaghfirullah_atubu" to DuaText("दैनिक इस्तिघफर", "हम अल्लाहसँ क्षमा माँगैत छी आ पश्चाताप करैत हुनका लग फिरैत छी।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम दिन मे सत्तरी सँ बेसी बेर क्षमा माँगैत छलाह।", "पैगम्बर सल्लल्लाहु अलैहि वसल्लम कहैत छथि, \"हम अल्लाह सँ क्षमा माँगैत छी आ दिन मे सत्तरी सँ बेसी बेर पश्चाताप करैत छी।"),
        "dua_laylatul_qadr" to DuaText("दुआ लाइलात अल-कदरक लेल", "ऐ अल्लाह, अहाँ बड्ड क्षमाशील छी आ क्षमा करबाक इच्छा करैत छी, तेँ हमरा क्षमा कऽ दियौक।", "लैलात अल-कदरक लेल आयशा (रा.) केँ सिखायल गेल।", "रमज़ान आ लैलात अल-कदरक अन्तिम राति लेल एकटा विशेष दुआ।"),
        "dua_family_coolness" to DuaText("आँखि के शीतलता (जीवनसाथी आ बच्चा)", "हमर प्रभु, हमरा सभ केँ हमर पति-पत्नी आ हमर सन्तान सभ सँ हमर आँखि के शीतलता प्रदान करू आ हमरा सभ केँ धार्मिक सभक नेता बनाउ।", "एक धर्मी जीवनसाथी आ बच्चासभक लेल कुरानिक दुआ।", "घर मे शान्ति आ धर्मी बच्चासभ लेल।"),
        "dua_righteous_children" to DuaText("धर्मी सन्तानक लेल", "हे हमर प्रभु, हमरा अपन पवित्र सन्तान प्रदान करू। निश्चय ही अहाँ प्रार्थना के सुनने छी।", "पैगम्बर ज़कारिया (अ. स.) के दुआ।", "बच्चा चाहैत लोकक लेल कुरानिक दुआ।"),
        "dua_ibrahim_prayer_family" to DuaText("प्रार्थनाक संस्थापकसभ", "हे हमर प्रभु, हमरा प्रार्थना करबाक लेल आ हमर सन्तान सभक लेल एक संस्थापक बनाउ। हमर प्रभु, हमर प्रार्थना स्वीकार करू। हमर प्रभु, हमरा, हमर माता-पिता आ विश्वासी सभ केँ क्षमा करू जाहि दिन लेखा स्थापित होयत।", "पैगम्बर इब्राहिम (अ. स.) के दुआ अपन आ अपन वंशज सभक लेल।", "सामान्यतः प्रार्थनाक अन्तमे पाठ कयल जाइत अछि।"),
        "dua_newlywed" to DuaText("नवविवाहितकेँ बधाई।", "अल्लाह अहाँ पर आशीर्वाद पठाउ आ अहाँ दुनू केँ भलाइक संग एक ठाम आनि दे।", "जखन कोनो व्यक्ति केँ ओकर विवाहक लेल बधाई दैत छी।", "सुन्ना विवाहक लेल बधाई दैत अछि।"),
        "dua_before_eating" to DuaText("भोजन करबासँ पहिने", "अल्लाह के नाम पर। (यदि भुला देल जाएः) अल्लाह के नाम पर, शुरू मे आ अंत मे।", "भोजन करबासँ पहिने। जँ अहाँ भूलैत छी तँ एकरा आंशिक रूप सँ कहि लिअ।", "बिस्मिल्लाह कहलासँ शयतान भोजन बाँटिबा सँ बचैत अछि।"),
        "dua_after_eating" to DuaText("भोजनक बाद", "प्रशंसा अछि अल्लाह के जे हमरा ई खिलाओल आ बिना कोनो शक्ति वा शक्ति के हमरा लेल ई प्रदान कयलनि।", "भोजन समाप्त भेलाक बाद।", "जे ई कहैत अछि ओकर पूर्व पाप क्षमा भऽ गेल अछि।"),
        "dua_host" to DuaText("मेजबान लेल", "ओ अल्लाह, अहाँ हुनका सभ केँ जे किछु देलहुँ, ताहि पर हुनका सभ केँ आशीर्वाद दियौक, हुनका सभ केँ क्षमा कऽ दियौक आ हुनका सभ पर दया करू।", "मेजबान लेल, कोनोक घर पर भोजन करबाक बाद।", "सुन्नाक रूपमे मेजबानकेँ धन्यवाद।"),
    )
}
